from pathlib import Pathimport sys# ============================================================# PROJECT ROOT# ============================================================PROJECT_ROOT = Path(__file__).resolve().parent.parentif str(PROJECT_ROOT) not in sys.path:    sys.path.insert(0, str(PROJECT_ROOT))# ============================================================# IMPORTS# ============================================================from datetime import datetime, timezonefrom typing import Any, Dict, Optionalimport pandas as pdfrom analysis.scalping_5m import analyze_5mfrom analysis.scalping_levels import generate_scalping_levelsfrom strategies.base_strategy import (    BaseStrategy,    StrategyResult,)from strategies.htf_adapter import (    get_htf_context,)class LiquiditySweepStrategy(BaseStrategy):    """    XAU/USD Liquidity Sweep Strategy.    Architecture:        V3.1 HTF Analysis                +             5M Engine                +        Liquidity Sweep                ↓          Final Strategy    Muhim:        5M setup = yakuniy signal emas.        V3.1 BUY + bullish 5M sweep  -> BUY        V3.1 SELL + bearish 5M sweep -> SELL        V3.1 WAIT                     -> NO_TRADE    Strategiya V3.1 HTF logikasini qayta hisoblamaydi.    """    strategy_id = "liquidity_sweep"    strategy_name = "Liquidity Sweep"    strategy_version = "1.1"    # ========================================================    # MAIN ANALYSIS    # ========================================================    def analyze(        self,        df_5m: pd.DataFrame,        htf_context: Optional[Dict[str, Any]] = None    ) -> StrategyResult:        result = StrategyResult(            strategy_id=self.strategy_id,            strategy_name=self.strategy_name,            strategy_version=self.strategy_version,            timeframe="5m",            analysis_time=datetime.now(                timezone.utc            ).isoformat(),        )        # ----------------------------------------------------        # VALIDATION        # ----------------------------------------------------        if df_5m is None or df_5m.empty:            result.status = "ERROR"            result.add_reason(                "5M data is empty."            )            return result        # ----------------------------------------------------        # EXISTING 5M ENGINE        # ----------------------------------------------------        try:            analysis = analyze_5m(                df_5m            )        except Exception as exc:            result.status = "ERROR"            result.add_reason(                f"5M analysis error: {exc}"            )            return result        if not analysis:            result.status = "ERROR"            result.add_reason(                "5M analysis returned no result."            )            return result        if analysis.get("status") != "OK":            result.status = analysis.get(                "status",                "ERROR"            )            result.add_reason(                analysis.get(                    "message",                    "5M analysis is not ready."                )            )            return result        # ----------------------------------------------------        # BASIC MARKET DATA        # ----------------------------------------------------        result.price = self._safe_float(            analysis.get("price")        )        result.trend_5m = analysis.get(            "direction"        )        # ----------------------------------------------------        # INDICATORS        # ----------------------------------------------------        result.indicators = {            "EMA20": analysis.get("ema20"),            "EMA50": analysis.get("ema50"),            "EMA200": analysis.get("ema200"),            "RSI": analysis.get("rsi"),            "MACD": analysis.get("macd"),            "MACD_SIGNAL": analysis.get("macd_signal"),            "MACD_HIST": analysis.get("macd_hist"),            "ATR": analysis.get("atr"),            "ADX": analysis.get("adx"),            "DI_PLUS": analysis.get("di_plus"),            "DI_MINUS": analysis.get("di_minus"),        }        # ----------------------------------------------------        # MARKET STRUCTURE        # ----------------------------------------------------        result.structure = {            "trend": analysis.get(                "structure"            ),            "high_structure": analysis.get(                "high_structure"            ),            "low_structure": analysis.get(                "low_structure"            ),            "bos": analysis.get(                "bos"            ),        }        # ----------------------------------------------------        # LIQUIDITY        # ----------------------------------------------------        liquidity_sweep = analysis.get(            "liquidity_sweep"        )        result.liquidity = {            "sweep": liquidity_sweep        }        # ----------------------------------------------------        # SETUP        # ----------------------------------------------------        if liquidity_sweep == "BULLISH_SWEEP":            result.setup = (                "BULLISH_LIQUIDITY_SWEEP"            )            result.add_confirmation(                "Bullish liquidity sweep detected"            )        elif liquidity_sweep == "BEARISH_SWEEP":            result.setup = (                "BEARISH_LIQUIDITY_SWEEP"            )            result.add_confirmation(                "Bearish liquidity sweep detected"            )        else:            result.setup = (                "NO_LIQUIDITY_SWEEP"            )            result.signal = "NO_TRADE"            result.status = "NO_TRADE"            result.add_reason(                "No confirmed liquidity sweep detected."            )            # HTF context baribir saqlanadi            self._apply_htf_context(                result,                htf_context            )            return result        # ----------------------------------------------------        # 5M INDICATOR CONFIRMATION        # ----------------------------------------------------        direction = analysis.get(            "direction"        )        if direction == "BULLISH":            result.add_confirmation(                "5M indicators are bullish"            )        elif direction == "BEARISH":            result.add_confirmation(                "5M indicators are bearish"            )        # ----------------------------------------------------        # 5M STRUCTURE CONFIRMATION        # ----------------------------------------------------        structure = str(            analysis.get(                "structure",                ""            )        ).upper()        if liquidity_sweep == "BULLISH_SWEEP":            if structure == "BULLISH":                result.add_confirmation(                    "5M structure is bullish"                )            else:                result.add_reason(                    "Bullish sweep exists but 5M "                    "structure is not bullish."                )        elif liquidity_sweep == "BEARISH_SWEEP":            if structure == "BEARISH":                result.add_confirmation(                    "5M structure is bearish"                )            else:                result.add_reason(                    "Bearish sweep exists but 5M "                    "structure is not bearish."                )        # ----------------------------------------------------        # HTF CONTEXT        # ----------------------------------------------------        self._apply_htf_context(            result,            htf_context        )        # ----------------------------------------------------        # FINAL SIGNAL        # ----------------------------------------------------        self._determine_final_signal(            result,            liquidity_sweep,            analysis,        )        # ----------------------------------------------------        # TRADE LEVELS        # ----------------------------------------------------        if result.signal in (            "BUY",            "SELL"        ):            try:                levels = generate_scalping_levels(                    df_5m,                    analysis                )            except Exception as exc:                levels = None                result.add_reason(                    f"Trade level calculation error: {exc}"                )            if (                levels                and levels.get("status") == "READY"            ):                result.entry = self._safe_float(                    levels.get("entry")                )                result.stop_loss = self._safe_float(                    levels.get("stop_loss")                )                result.tp1 = self._safe_float(                    levels.get("tp1")                )                result.tp2 = self._safe_float(                    levels.get("tp2")                )                result.risk = self._safe_float(                    levels.get("risk")                )                result.rr_tp1 = self._safe_float(                    levels.get("rr_tp1")                )                result.rr_tp2 = self._safe_float(                    levels.get("rr_tp2")                )                result.metadata["sl_method"] = (                    levels.get("sl_method")                )                result.metadata["candle_time"] = (                    levels.get("candle_time")                )            else:                result.add_reason(                    "Trade signal exists but trade "                    "levels could not be generated."                )        return result    # ========================================================    # FINAL SIGNAL    # ========================================================    def _determine_final_signal(        self,        result: StrategyResult,        liquidity_sweep: Optional[str],        analysis: Dict[str, Any],    ):        # ----------------------------------------------------        # 1. V3.1 MUST CONFIRM A DIRECTION        # ----------------------------------------------------        v31_signal = result.metadata.get(            "v31_signal",            "WAIT"        )        if v31_signal not in (            "BUY",            "SELL"        ):            result.signal = "NO_TRADE"            result.status = "NO_TRADE"            result.add_reason(                "V3.1 did not confirm a BUY or SELL signal."            )            return        # ----------------------------------------------------        # 2. BULLISH SWEEP        # ----------------------------------------------------        if liquidity_sweep == "BULLISH_SWEEP":            if v31_signal != "BUY":                result.signal = "NO_TRADE"                result.status = "NO_TRADE"                result.add_reason(                    "Bullish liquidity sweep conflicts "                    "with V3.1 signal."                )                return            if str(                analysis.get(                    "direction",                    ""                )            ).upper() != "BULLISH":                result.signal = "NO_TRADE"                result.status = "NO_TRADE"                result.add_reason(                    "Bullish liquidity sweep is not "                    "confirmed by 5M indicator direction."                )                return            result.signal = "BUY"            result.status = "READY"            result.add_reason(                "V3.1 BUY is aligned with bullish "                "5M liquidity sweep."            )            return        # ----------------------------------------------------        # 3. BEARISH SWEEP        # ----------------------------------------------------        if liquidity_sweep == "BEARISH_SWEEP":            if v31_signal != "SELL":                result.signal = "NO_TRADE"                result.status = "NO_TRADE"                result.add_reason(                    "Bearish liquidity sweep conflicts "                    "with V3.1 signal."                )                return            if str(                analysis.get(                    "direction",                    ""                )            ).upper() != "BEARISH":                result.signal = "NO_TRADE"                result.status = "NO_TRADE"                result.add_reason(                    "Bearish liquidity sweep is not "                    "confirmed by 5M indicator direction."                )                return            result.signal = "SELL"            result.status = "READY"            result.add_reason(                "V3.1 SELL is aligned with bearish "                "5M liquidity sweep."            )            return        # ----------------------------------------------------        # 4. NO SWEEP        # ----------------------------------------------------        result.signal = "NO_TRADE"        result.status = "NO_TRADE"    # ========================================================    # HTF CONTEXT    # ========================================================    def _apply_htf_context(        self,        result: StrategyResult,        htf_context: Optional[Dict[str, Any]]    ):        if not htf_context:            result.htf_agreement = "UNKNOWN"            result.metadata["v31_signal"] = "WAIT"            result.add_reason(                "Higher-timeframe context was not provided."            )            return        # ----------------------------------------------------        # V3.1 DIRECTIONS        # ----------------------------------------------------        result.trend_1d = htf_context.get(            "1d"        )        result.trend_4h = htf_context.get(            "4h"        )        result.trend_1h = htf_context.get(            "1h"        )        result.trend_15m = htf_context.get(            "15m"        )        # ----------------------------------------------------        # V3.1 SIGNAL        # ----------------------------------------------------        result.metadata["v31_signal"] = htf_context.get(            "signal",            "WAIT"        )        result.metadata["v31_confidence"] = htf_context.get(            "confidence"        )        result.metadata["v31_confirmations"] = htf_context.get(            "confirmations"        )        result.metadata["v31_market_phase"] = htf_context.get(            "market_phase"        )        result.metadata["v31_entry_trigger"] = htf_context.get(            "entry_trigger"        )        result.metadata["v31_support"] = htf_context.get(            "support"        )        result.metadata["v31_resistance"] = htf_context.get(            "resistance"        )        result.metadata["v31_reasons"] = list(            htf_context.get(                "reasons",                []            )        )        # ----------------------------------------------------        # HTF AGREEMENT        # ----------------------------------------------------        result.htf_agreement = htf_context.get(            "htf_agreement",            "UNKNOWN"        )        # ----------------------------------------------------        # ADD V3.1 CONFIRMATION        # ----------------------------------------------------        v31_signal = htf_context.get(            "signal",            "WAIT"        )        if v31_signal == "BUY":            result.add_confirmation(                "V3.1 HTF engine confirmed BUY"            )        elif v31_signal == "SELL":            result.add_confirmation(                "V3.1 HTF engine confirmed SELL"            )        else:            result.add_reason(                "V3.1 HTF engine is currently WAIT."            )    # ========================================================    # UTILITY    # ========================================================    @staticmethod    def _safe_float(value):        if value is None:            return None        try:            value = float(value)            if pd.isna(value):                return None            return value        except (            TypeError,            ValueError        ):            return None# ============================================================# DIRECT TEST# ============================================================if __name__ == "__main__":    from data.market_data import (        get_xauusd_candles    )    print("=" * 70)    print(        "XAU_AI LIQUIDITY SWEEP + V3.1 TEST"    )    print("=" * 70)    print()    print("Loading 5M data...")    df = get_xauusd_candles(        "5m",        300    )    if df is None or df.empty:        raise RuntimeError(            "5M market data olinmadi."        )    print(        f"Loaded candles: {len(df)}"    )    # --------------------------------------------------------    # V3.1 HTF CONTEXT    # --------------------------------------------------------    print()    print("-" * 70)    print("Loading V3.1 HTF context...")    print("-" * 70)    try:        htf_context = get_htf_context()    except Exception as exc:        print(            f"[ERROR] HTF context: "            f"{type(exc).__name__}: {exc}"        )        raise    if htf_context.get("status") != "OK":        raise RuntimeError(            htf_context.get(                "message",                "HTF context error."            )        )    print(        "V3.1 SIGNAL:",        htf_context.get("signal")    )    print(        "V3.1 CONFIRMATIONS:",        htf_context.get("confirmations")    )    print(        "V3.1 CONFIDENCE:",        htf_context.get("confidence")    )    print(        "HTF AGREEMENT:",        htf_context.get("htf_agreement")    )    print()    print(        "1D:",        htf_context.get("1d")    )    print(        "4H:",        htf_context.get("4h")    )    print(        "1H:",        htf_context.get("1h")    )    print(        "15M:",        htf_context.get("15m")    )    # --------------------------------------------------------    # STRATEGY    # --------------------------------------------------------    strategy = LiquiditySweepStrategy()    result = strategy.analyze(        df_5m=df,        htf_context=htf_context,    )    # --------------------------------------------------------    # RESULT    # --------------------------------------------------------    print()    print("=" * 70)    print(        "STRATEGY:",        result.strategy_name    )    print(        "VERSION:",        result.strategy_version    )    print(        "SIGNAL:",        result.signal    )    print(        "STATUS:",        result.status    )    print(        "PRICE:",        result.price    )    print(        "SETUP:",        result.setup    )    print(        "5M TREND:",        result.trend_5m    )    print(        "1D:",        result.trend_1d    )    print(        "4H:",        result.trend_4h    )    print(        "1H:",        result.trend_1h    )    print(        "15M:",        result.trend_15m    )    print(        "HTF AGREEMENT:",        result.htf_agreement    )    print(        "V3.1 SIGNAL:",        result.metadata.get(            "v31_signal"        )    )    print(        "V3.1 CONFIRMATIONS:",        result.metadata.get(            "v31_confirmations"        )    )    print(        "V3.1 CONFIDENCE:",        result.metadata.get(            "v31_confidence"        )    )    print(        "ENTRY:",        result.entry    )    print(        "STOP LOSS:",        result.stop_loss    )    print(        "TP1:",        result.tp1    )    print(        "TP2:",        result.tp2    )    print(        "RISK:",        result.risk    )    print(        "RR TP1:",        result.rr_tp1    )    print(        "RR TP2:",        result.rr_tp2    )    print(        "CONFIRMATIONS:",        result.confirmation_count    )    print()    print("CONFIRMATION LIST:")    print("-" * 70)    for item in result.confirmations:        print(            " -",            item        )    print()    print("REASONS:")    print("-" * 70)    for reason in result.reasons:        print(            " -",            reason        )    print()    print("=" * 70)    print("TEST FINISHED")    print("=" * 70)